class Solution:
    def checkValid(self, matrix: List[List[int]]) -> bool:
        if not matrix:
            return True
        n = len(matrix)
        m = len(matrix[0])
        # Track seen numbers in each row and each column
        dp_row = [[False] * m for _ in range(n)]
        dp_col = [[False] * m for _ in range(n)]

        for i in range(n):
            for j in range(m):
                val = matrix[i][j]
                # Values must be in the range 1..m (assuming a square matrix)
                if val < 1 or val > m:
                    return False
                idx = val - 1
                if dp_row[i][idx] or dp_col[j][idx]:
                    return False
                dp_row[i][idx] = True
                dp_col[j][idx] = True
