        target = ((1, 2, 3), (4, 5, 0))

        def find_zero(b):
            for i in range(2):
                for j in range(3):
                    if b[i][j] == 0:
                        return i, j
            return -1, -1

        def neighbors(b):
            res = []
            r, c = find_zero(b)
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < 2 and 0 <= nc < 3:
                    # proper copy of the board
                    nb = [row[:] for row in b]
                    # swap zero with adjacent tile
                    nb[r][c], nb[nr][nc] = nb[nr][nc], 0
                    res.append(nb)
            return res

        start = tuple(tuple(row) for row in board)
        if start == target:
            return 0

        q = deque()
        q.append((board, 0))
        seen = {start}

        while q:
            cur, moves = q.popleft()
            for nxt in neighbors(cur):
                nxt_t = tuple(tuple(row) for row in nxt)
                if nxt_t == target:
                    return moves + 1
                if nxt_t not in seen:
                    seen.add(nxt_t)
                    q.append((nxt, moves + 1))
        return -1

