from collections import defaultdict
from typing import List

class Solution:
    def fourSumCount(self, nums1: List[int], nums2: List[int], nums3: List[int], nums4: List[int]) -> int:
        pair_sum = defaultdict(int)
        for n1 in nums1:
            for n2 in nums2:
                pair_sum[-(n1 + n2)] += 1

        result = 0
        for n3 in nums3:
            for n4 in nums4:
                result += pair_sum.get(n3 + n4, 0)

        return result

