class Solution:
    def longestWPI(self, A):
        curr = 0
        ans = 0
        D = {}
        for e, i in enumerate(map(lambda x: 1 if x > 8 else -1, A)):
            curr += i
            D.setdefault(curr, e)
            if curr > 0:
                ans = e + 1
            else:
                ans = max(ans, e - D.get(curr - 1, e))
        return ans

